using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must explicitly preserve it.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 uses only the raw key for "id" (e.g. "1").
        // Existing documents store id as "Blog|1", so we preserve that format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<BlogIdGenerator>();

        // Breaking change 3: EF Core 9 no longer supports indexes on Cosmos DB
        // (Cosmos manages indexes automatically). The HasIndex call has been removed.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

// Value generator that preserves the "Blog|{key}" id format for existing documents.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class BlogIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry) => $"Blog|{Guid.NewGuid()}";
}

